function visibleTabs(){const ph=eventPhase(),intro=['intro','活動介紹'],agenda=['agenda','活動議程'],survey=['survey','現場問卷'],results=['results','活動成果'];if(ph==='ended')return [results,intro,agenda,survey];if(ph==='soon')return [intro,agenda];return [intro,agenda,survey,results]}
function recapTeaser(recap){return `<div class="result-teaser"><span class="badge">活動成果已發布</span><h3>${esc(recap.title)}</h3>${recapFactsHTML(recap,recap.event||state.event)}<p class="bodycopy">${esc(recap.summary)}</p><a class="download-link" href="/recap/?e=${encodeURIComponent(state.id)}">查看完整活動成果 Landing page ↗</a><div class="teaser-photos">${recap.assets.filter(a=>a.type?.startsWith('image/')).slice(0,3).map(a=>mediaURL(a.id)?`<img src="${mediaURL(a.id)}" alt="${esc(a.caption||a.name)}">`:'').join('')}</div></div>`}
function visitor(){const e=state.event,reason=registrationReason(),count=state.registrations.length,ph=eventPhase(),tabs=visibleTabs();if(!tabs.some(([v])=>v===tab))tab=tabs[0][0];
 const badge=state.registered?'已完成示範報名':ph==='open'?(reason||'開放報名中'):PHASE_LABEL[ph];
 const info=ph==='soon'?`<p class="fine">報名開放時間：${esc(e.regStart?e.regStart.replace('T',' ')+'（台北）':'即將公布')}</p>`:ph==='ended'?`<p class="fine">共 ${count} 人報名</p>`:`<div class="progress"><div style="width:${Math.min(100,count/e.capacity*100)}%"></div></div><p class="fine">已報名 ${count} / ${e.capacity} 人<br>截止時間：${esc(e.deadline.replace('T',' '))}（台北）</p>`;
 const label=state.registered?'✓ 已報名':ph==='soon'?'即將開放報名':reason||'立即報名 ↗';
 return `<div class="layout"><section class="card">${hero()}<div class="tabs">${tabs.map(([value,l])=>`<button class="${tab===value?'on':''}" onclick="setTab('${value}')">${l}</button>`).join('')}</div><div class="content">${visitorContent()}</div></section><aside><section class="card side"><span class="badge">${esc(badge)}</span><h3>${esc(e.name)}</h3><div class="details"><div><span>活動時間</span>${esc(dateLabel())}<br>${esc(e.start)} – ${esc(e.end)} · Asia/Taipei</div><div><span>活動地點</span>${esc(e.venue)}<br><small class="fine">${esc(e.mode)}</small></div><div><span>適合對象</span>${esc(e.audience)}</div></div>${info}${ph==='ended'&&!state.registered?'':`<button class="primary full" onclick="openRegistration()" ${reason&&!state.registered?'disabled':''}>${label}</button>`}${ph==='open'?'<p class="fine" style="text-align:center">活動與報名為 Demo · 不寄送通知信</p>':''}</section>${ph==='soon'?'':`<section class="note"><div class="eyebrow">AFTER THE EVENT</div><h4 style="margin-top:12px">精彩，不只留在現場。</h4><p>活動成果經 MKT 審核發布後，將提供完整回顧、現場照片、影片與分享簡報。</p>${state.publishedRecap?`<a class="download-link" href="/recap/?e=${encodeURIComponent(state.id)}">前往活動成果頁 ↗</a>`:''}</section>`}</aside></div>`}
function visitorContent(){const e=state.event;if(tab==='intro')return `<div class="eyebrow">ABOUT THIS SESSION</div><h3 style="margin-top:15px">${esc(e.tagline||e.name)}</h3><p class="bodycopy" style="white-space:pre-wrap">${esc(e.intro)}</p><div class="topics"><div class="topic"><small>LEARN</small><h4>探索新方法</h4><p>從分享與實作中，發現更多可能。</p></div><div class="topic"><small>CONNECT</small><h4>連結不同觀點</h4><p>與跨團隊夥伴交流經驗。</p></div><div class="topic"><small>CREATE</small><h4>延續活動收穫</h4><p>在成果頁重溫活動精彩片段。</p></div></div>`;
  if(tab==='agenda')return `<h3>活動議程</h3>${e.agenda.split('\n').filter(s=>s.trim()).map(line=>{const [time,...parts]=line.split('｜');return `<div class="agenda"><b>${esc(parts.length?time:'')}</b><div>${esc(parts.length?parts.join('｜'):time)}</div></div>`}).join('')||'<div class="empty">議程即將公布。</div>'}`;
  if(tab==='survey')return `<div class="eyebrow">YOUR VOICE MATTERS</div><h3 style="margin-top:15px">今天的交流，帶給你什麼？</h3><p class="fine">${state.questions.length} 個問題 · 回覆僅儲存在此瀏覽器。</p>${state.surveyOpen?surveyForm():'<div class="empty">問卷目前未開放填答。</div>'}`;
  if(!state.publishedRecap)return '<div class="empty"><h3>精彩成果，整理中。</h3>成果頁經審核發布後，將在這裡優先呈現。</div>';
  return recapTeaser(state.publishedRecap);
}
function openRegistration(){if(state.registered){toast('你已完成此瀏覽器的示範報名');return}const reason=registrationReason();if(reason){toast(reason);return}const e=state.event;$('regDialog').classList.add('registration-dialog');$('regForm').innerHTML=`<div class="eyebrow">JOIN THE CONVERSATION</div><h2>報名 ${esc(e.name)}</h2><p class="fine">Demo 請使用示範資料。資料僅儲存在此瀏覽器，不寄送通知信。</p>${registrationFieldsHTML(e)}<label class="checkline"><input type="checkbox" required> 我了解這是本機示範報名</label><div class="actions"><button class="primary">確認報名</button><button type="button" onclick="$('regDialog').close()">取消</button></div>`;$('regDialog').showModal()}
$('regForm').onsubmit=e=>{e.preventDefault();const reason=registrationReason();if(reason){toast(reason);return}const f=new FormData(e.target),config=registrationConfig(),entry={date:timestamp()};for(const spec of REGISTRATION_FIELDS){const value=config[spec.id].enabled?String(f.get(spec.input)||'').trim():'';if(config[spec.id].required&&!value){toast('請填寫'+spec.label);return}entry[spec.id]=value}entry.email=entry.email.toLowerCase();if(state.registrations.some(r=>r.email===entry.email)){toast('這個 Email 已經報名');return}state.registrations.push(entry);state.registered=true;if(save()){$('regDialog').close();render();toast('示範報名成功，未寄送通知信')}};
function submitSurvey(e){e.preventDefault();if(!state.surveyOpen){toast('問卷已停止填答');return}const f=new FormData(e.target),answers=[];for(const q of state.questions){const value=q.type==='multi'?f.getAll('q_'+q.id):f.get('q_'+q.id)||'';if(q.required&&(!value||(Array.isArray(value)&&!value.length))){toast('請完成必填問題：'+q.title);return}answers.push({id:q.id,title:q.title,type:q.type,value})}state.responses.push({date:timestamp(),version:state.surveyVersion,answers});if(save()){e.target.reset();toast('問卷已送出，感謝你的回饋')}}
function setTab(value){tab=value;render()}
const LIST_H1='讓交流，成為下一個靈感。';
function eventTags(e){return String(e.tags||'').split(/[,，、\n]/).map(t=>t.trim().replace(/^#/,'')).filter(Boolean).slice(0,6)}
function dateLine(e){if(!e.date)return '時間待公布';const d=new Date(e.date+'T12:00:00+08:00'),wk=Number.isNaN(d.getTime())?'':d.toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei',weekday:'short'});return `${e.date.replace(/-/g,'.')}${wk?' ('+wk+')':''} ${e.start||''} – ${e.end||''}`}
function tagsHTML(e){const t=eventTags(e);return t.length?`<div class="event-tags">${t.map(x=>`<a href="/?q=${encodeURIComponent(x)}" data-q="${esc(x)}">#${esc(x)}</a>`).join('')}</div>`:''}
function listCard(ev,force){const e=ev.event,ph=force?'ended':eventPhase(ev),reason=registrationReason(ev),id=encodeURIComponent(ev.id),recap=ev.publishedRecap;
 const banner=e.bannerMode==='image'&&e.bannerId&&mediaURL(e.bannerId);
 let media=bannerMedia(e);
 if(ph==='ended'&&recap){const photos=recap.assets.filter(a=>a.type?.startsWith('image/')),cover=photos.find(a=>a.id===recap.coverId)||photos[0],url=cover&&mediaURL(cover.id);if(url)media=`<img src="${url}" alt="${esc(cover.caption||recap.title)}">`}
 const loc=`<p class="event-loc">${esc(e.venue)}　/　${esc(e.mode)}</p>`;
 if(ph==='ended')return `<article class="event-card ended"><div class="event-card-media"><span class="badge status phase-ended">已結束</span>${media}</div><div class="event-card-body"><p class="event-date">${esc(dateLine(e))}</p><h3>${esc(e.name)}</h3>${loc}${tagsHTML(e)}${recap?`<div class="eyebrow">EVENT RECAP</div><h4>${esc(recap.title)}</h4>${recapFactsHTML(recap,recap.event||e)}<p class="event-summary">${esc(recap.summary)}</p><div class="actions"><a class="download-link" href="/recap/?e=${id}">查看活動成果 ↗</a><a class="download-link" href="/?e=${id}">活動詳情</a></div>`:`<p class="bodycopy">成果整理中，發布後將於此優先顯示。</p><div class="actions"><a class="download-link" href="/?e=${id}">活動詳情</a></div>`}</div></article>`;
 const foot=ph==='soon'?`<p class="fine">報名開放：${esc(e.regStart?e.regStart.replace('T',' ')+'（台北）':'即將公布')}</p>`:`<div class="progress"><div style="width:${Math.min(100,ev.registrations.length/e.capacity*100)}%"></div></div><p class="fine">已報名 ${ev.registrations.length} / ${e.capacity} 人</p>`;
 const badge=ph==='soon'?'Coming soon':reason?reason:'報名中';
 return `<article class="event-card ac h" tabindex="0" data-href="/?e=${id}"><div class="event-card-media"><span class="badge status phase-${ph}">${esc(badge)}</span>${media}</div><div class="event-card-body"><p class="event-date">${esc(dateLine(e))}</p><h3>${esc(e.name)}</h3>${loc}${tagsHTML(e)}${foot}<div class="actions"><a class="download-link" href="/?e=${id}">${ph==='soon'?'查看活動介紹':reason?'查看活動':'查看活動並報名 ↗'}</a></div></div></article>`}
function bannerMini(e){return `<div class="banner-mini"><small>EXPERTHUB SESSIONS</small><b>${esc(e.name)}</b>${e.tagline?`<span>${esc(e.tagline)}</span>`:''}<em>${esc(dateLabel(e.date))}　/　${esc(e.mode)}</em></div>`}
function bannerMedia(e){const cu=e.cardImageId&&mediaURL(e.cardImageId);if(cu)return `<img src="${cu}" alt="${esc(e.bannerAlt||e.name)}">`;const url=e.bannerMode==='image'&&e.bannerId&&mediaURL(e.bannerId);if(url)return `<img src="${url}" alt="${esc(e.bannerAlt||e.name)}">${e.bannerShowText?`<div class="banner-mini overlay"><b>${esc(e.name)}</b>${e.tagline?`<span>${esc(e.tagline)}</span>`:''}<em>${esc(dateLabel(e.date))}　/　${esc(e.mode)}</em></div>`:''}`;return bannerMini(e)}
const PIN='<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" fill="#9aa59c"><path d="M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 9.5A2.5 2.5 0 1 1 12 6a2.5 2.5 0 0 1 0 5.5z"/></svg>';
function gridCard(ev){const e=ev.event,ph=eventPhase(ev),reason=registrationReason(ev),id=encodeURIComponent(ev.id),recap=ev.publishedRecap,hasRecap=ph==='ended'&&!!recap;
 const media=bannerMedia(e);
 const badge=ph==='ended'?'已結束':ph==='soon'?'Coming soon':reason||'報名中';
 const info=ph==='soon'?`報名開放：${e.regStart?e.regStart.replace('T',' ')+'（台北）':'即將公布'}`:ph==='ended'?(recap?'':'成果整理中'):`已報名 ${ev.registrations.length} / ${e.capacity} 人`;
 const href=hasRecap?`/recap/?e=${id}`:`/?e=${id}`;
 return `<article class="event-card g" tabindex="0" data-href="${href}"><div class="event-card-media"><span class="badge status phase-${ph}">${esc(badge)}</span>${media}</div><div class="event-card-body"><p class="event-date">${esc(dateLine(e))}</p><h3>${esc(e.name)}</h3><p class="event-loc">${PIN}<span>${esc(e.venue)}</span></p></div><div class="event-card-foot">${tagsHTML(e)}${info?`<span class="fine">${esc(info)}</span>`:''}${hasRecap?`<a class="download-link" href="/recap/?e=${id}">查看活動成果 ↗</a>`:''}</div></article>`}
const EXPLORE={q:'',tab:'all',mode:'',month:''};
{const qp=new URLSearchParams(location.search);EXPLORE.q=(qp.get('q')||'').trim();EXPLORE.tab=['open','soon','ended'].includes(qp.get('tab'))?qp.get('tab'):'all';EXPLORE.mode=qp.get('mode')||'';EXPLORE.month=qp.get('month')||''}
function matchEvent(ev){const e=ev.event;if(EXPLORE.mode&&e.mode!==EXPLORE.mode)return false;if(EXPLORE.month&&!(e.date||'').startsWith(EXPLORE.month))return false;const terms=EXPLORE.q.toLowerCase().split(/\s+/).filter(Boolean);if(!terms.length)return true;const r=ev.publishedRecap,hay=[e.name,e.tagline,e.intro,e.venue,e.mode,e.audience,e.tags,r?.title,r?.summary].join(' ').toLowerCase();return terms.every(t=>hay.includes(t.replace(/^#/,'')))}
function syncExploreURL(){const p=new URLSearchParams();if(EXPLORE.q)p.set('q',EXPLORE.q);if(EXPLORE.tab!=='all')p.set('tab',EXPLORE.tab);if(EXPLORE.mode)p.set('mode',EXPLORE.mode);if(EXPLORE.month)p.set('month',EXPLORE.month);history.replaceState(null,'',location.pathname+(p.toString()?'?'+p:''))}
function setExplore(key,value){EXPLORE[key]=value;syncExploreURL();render()}
function clearExplore(){Object.assign(EXPLORE,{q:'',tab:'all',mode:'',month:''});syncExploreURL();render()}
function visitorList(){const dateOf=ev=>ev.event.date||'';
 const monthOf=ev=>(ev.event.date||'').slice(0,7),months=[...new Set(root.events.map(monthOf).filter(Boolean))].sort().reverse(),modes=[...new Set(root.events.map(ev=>ev.event.mode).filter(Boolean))];
 const matched=root.events.filter(matchEvent),by=p=>matched.filter(ev=>eventPhase(ev)===p);
 const open=by('open').sort((a,b)=>dateOf(a).localeCompare(dateOf(b))),soon=by('soon').sort((a,b)=>dateOf(a).localeCompare(dateOf(b))),ended=by('ended').sort((a,b)=>dateOf(b).localeCompare(dateOf(a)));
 const filtered=!!(EXPLORE.q||EXPLORE.mode||EXPLORE.month);
 const tabs=[['all','全部',matched.length],['open','報名中',open.length],['soon','Coming soon',soon.length],['ended','已結束',ended.length]];
 const bar=`<div class="explore-tabs" role="tablist">${tabs.map(([k,l,n])=>`<button role="tab" aria-selected="${EXPLORE.tab===k}" class="${EXPLORE.tab===k?'on':''}" onclick="setExplore('tab','${k}')">${l}<small>${n}</small></button>`).join('')}</div><div class="filter-row"><label>活動形式<select onchange="setExplore('mode',this.value)"><option value="">全部</option>${modes.map(m=>`<option ${EXPLORE.mode===m?'selected':''} value="${esc(m)}">${esc(m)}</option>`).join('')}</select></label><label>活動月份<select onchange="setExplore('month',this.value)"><option value="">全部</option>${months.map(m=>`<option ${EXPLORE.month===m?'selected':''} value="${m}">${m.replace('-',' 年 ')} 月</option>`).join('')}</select></label>${EXPLORE.q?`<span class="fine">搜尋「${esc(EXPLORE.q)}」</span>`:''}${filtered||EXPLORE.tab!=='all'?'<button type="button" onclick="clearExplore()">清除條件</button>':''}</div>`;
 const list=EXPLORE.tab==='open'?open:EXPLORE.tab==='soon'?soon:EXPLORE.tab==='ended'?ended:[...open,...soon,...ended];
 const body=list.length?(EXPLORE.tab==='ended'?`<div class="event-list-h">${list.map(x=>listCard(x)).join('')}</div>`:`<div class="event-grid-3">${list.map(gridCard).join('')}</div>`):`<div class="empty" style="margin-top:30px">${matched.length?'此分類目前沒有符合條件的活動。':`<h3>找不到符合條件的活動</h3><p>請調整關鍵字、活動形式或月份。</p><button type="button" onclick="clearExplore()">清除條件</button>`}</div>`;
 return bar+body}
let detail=false;const resultsPage=new URLSearchParams(location.search).get('page')==='results';
function resultsList(){const list=root.events.filter(ev=>ev.publishedRecap).sort((a,b)=>(b.event.date||'').localeCompare(a.event.date||''));return `<section class="event-section"><div class="sectiontitle"><div><div class="eyebrow">EVENT RECAPS</div><h2>已發布的活動成果</h2></div><span class="fine">${list.length} 場</span></div>${list.length?`<div class="event-grid ended-grid">${list.map(x=>listCard(x,true)).join('')}</div>`:'<div class="empty">目前尚無已發布的活動成果。</div>'}</section>`}
{const qp=new URLSearchParams(location.search),e=qp.get('e'),v=qp.get('view');detail=!resultsPage&&!EXPLORE.q&&(!!(e&&root.events.some(x=>x.id===e))||(!e&&!!v));
 if(detail){tab=eventPhase()==='ended'?'results':'intro';if(['results','survey'].includes(v)&&visibleTabs().some(([x])=>x===v))tab=v}}
function render(){const si=document.querySelector('.site-search input');if(si&&document.activeElement!==si)si.value=EXPLORE.q;const app=$('app'),crumb=document.querySelector('.crumb'),h1=document.querySelector('main h1'),subEl=document.querySelector('.sub');
 $('navResults')?.classList.toggle('active',resultsPage);$('navExplore')?.classList.toggle('active',!resultsPage);
 if(subEl)subEl.textContent=resultsPage?'回顧每一場活動的精彩片刻、照片與分享資料。':'從一次相聚，到持續累積的團隊知識。';
 if(resultsPage){crumb.textContent='EXPERTHUB / 活動成果';h1.textContent='每一場交流，都留下了成果。';document.title='EXPERTHUB — 活動成果';app.innerHTML=resultsList();return}
 if(!detail){crumb.textContent='EXPERTHUB / 活動探索';h1.textContent=LIST_H1;document.title='EXPERTHUB — 活動探索';app.innerHTML=visitorList();return}
 app.innerHTML=visitor();h1.textContent=state.event.tagline||state.event.name;crumb.innerHTML='EXPERTHUB　/　<a href="/">活動探索</a>　/　'+esc(state.event.name);document.title='EXPERTHUB — '+state.event.name}
{const form=document.querySelector('.site-search');if(form)form.addEventListener('submit',ev=>{ev.preventDefault();const v=form.q.value.trim();if(resultsPage){location.href='/'+(v?'?q='+encodeURIComponent(v):'');return}EXPLORE.q=v;EXPLORE.tab='all';detail=false;syncExploreURL();render();window.scrollTo(0,0)})}
document.addEventListener('click',ev=>{const t=ev.target,tag=t.closest?.('[data-q]');if(tag){ev.preventDefault();ev.stopPropagation();if(resultsPage){location.href='/?q='+encodeURIComponent(tag.dataset.q);return}EXPLORE.q=tag.dataset.q;EXPLORE.tab='all';detail=false;syncExploreURL();render();window.scrollTo(0,0);return}if(t.closest?.('a,button,select,input'))return;const card=t.closest?.('[data-href]');if(card)location.href=card.dataset.href},true);
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.dataset?.href)location.href=ev.target.dataset.href});
render();hydrateMedia().then(()=>render());
